    def __init__(self, clock: Callable[[], float] = time.perf_counter) -> None:
        self._clock = clock
        self._started: Optional[float] = None
        self.elapsed = 0.0

    def start(self) -> None:
        self._started = self._clock()

    def stop(self) -> float:
